// HasKek applies the HasEdge predicate on the "kek" edge.
func HasKek() predicate.DataKey {
	return predicate.DataKey(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, false, KekTable, KekColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasKekWith applies the HasEdge predicate on the "kek" edge with a given conditions (other predicates).
func HasKekWith(preds ...predicate.KEK) predicate.DataKey {
	return predicate.DataKey(func(s *sql.Selector) {
		step := newKekStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

